+fn fuse<'a>(b: &Builder<'a>, core: &'a Core<'a>) -> &'a Core<'a> {
+    use nash_ir::core::CoreKind;
+    let mut uses = std::collections::HashMap::<u32, usize>::new();
+    core.walk(&mut |n| if let CoreKind::Var(v) = n.kind {
+        *uses.entry(v.unique).or_default() += 1;
+    });
+    let result = core.map(b, &mut |n| {
+        let CoreKind::Let { binder, value, body } = n.kind else { return None; };
+        if uses.get(&binder.name.unique) != Some(&1) { return None; }
+        let CoreKind::App { func, args } = value.kind else { return None; };
+        let CoreKind::App { func: next, args: later } = body.kind else { return None; };
+        if !matches!(next.kind, CoreKind::Var(v) if v.unique == binder.name.unique)
+            || args.is_empty() || later.is_empty() || !anf::is_atom(func)
+            || !args.iter().chain(later).all(|x| anf::is_atom(x)) {
+            return None;
+        }
+        // Trial keeps exact intermediate type views; broader cases are untested.
+        if value.ty != binder.ty || next.ty != binder.ty || body.ty != n.ty { return None; }
+        let args = args.iter().chain(later).copied().collect::<Vec<_>>();
+        eprintln!("FUSED {} arguments", args.len());
+        Some(b.app(func, &args, n.ty))
+    });
+    anf::validate(result).unwrap();
+    hygiene::validate(result, &[]).unwrap();
+    assert_eq!(core.ty, result.ty);
+    result
+}
